import numpy as np
from flask import Flask, request, jsonify
import hashlib
import hmac
import os
import struct

app = Flask(__name__)
API_SECRET = os.environ.get('API_SECRET', os.urandom(32).hex())

class SecureRingBuffer:
    """Ring buffer for time-series sensor data with overflow protection."""

    def __init__(self, capacity=1024):
        self.capacity = capacity
        self.buffer = np.zeros(capacity, dtype=np.float64)
        self.metadata = np.zeros(capacity, dtype=np.int64)
        self.write_pos = np.int32(0)
        self.count = np.int32(0)

    def _compute_index(self, offset):
        """Compute buffer index with wraparound.
        Uses modular arithmetic to ensure index stays within bounds."""
        # offset is validated to be within int32 range before calling
        pos = self.write_pos + np.int32(offset)
        return int(pos % np.int32(self.capacity))

    def write_batch(self, timestamps, values):
        """Write a batch of sensor readings.

        Args:
            timestamps: list of int64 timestamps
            values: list of float64 sensor values
        Returns:
            Number of values successfully written
        """
        if len(timestamps) != len(values):
            raise ValueError("timestamps and values must have same length")

        written = 0
        for i in range(len(values)):
            idx = self._compute_index(i)
            if 0 <= idx < self.capacity:
                self.buffer[idx] = values[i]
                self.metadata[idx] = timestamps[i]
                written += 1
            else:
                # This shouldn't happen due to modulo, but safety check
                break

        self.count = np.int32(min(self.count + len(values), self.capacity))
        self.write_pos = np.int32((self.write_pos + np.int32(len(values))) % np.int32(self.capacity))
        return written

    def read_range(self, start_offset, length):
        """Read a range of values from the buffer."""
        results = []
        for i in range(min(length, int(self.count))):
            idx = int((self.write_pos - np.int32(self.count) + np.int32(start_offset + i)) % np.int32(self.capacity))
            if 0 <= idx < self.capacity:
                results.append({
                    'timestamp': int(self.metadata[idx]),
                    'value': float(self.buffer[idx])
                })
        return results

    def get_stats(self):
        """Get buffer statistics."""
        if self.count == 0:
            return {'count': 0, 'mean': 0.0, 'max': 0.0, 'min': 0.0}
        active = self.buffer[:int(self.count)]
        return {
            'count': int(self.count),
            'mean': float(np.mean(active)),
            'max': float(np.max(active)),
            'min': float(np.min(active))
        }


# Global buffer instance
sensor_buffer = SecureRingBuffer(capacity=1024)


def verify_request(req):
    """Verify HMAC signature on incoming requests."""
    signature = req.headers.get('X-Signature')
    timestamp = req.headers.get('X-Timestamp')
    if not signature or not timestamp:
        return False

    try:
        ts = int(timestamp)
        import time
        if abs(time.time() - ts) > 300:  # 5 minute window
            return False
    except (ValueError, TypeError):
        return False

    message = f"{req.method}:{req.path}:{timestamp}:{req.get_data(as_text=True)}"
    expected = hmac.new(
        API_SECRET.encode() if isinstance(API_SECRET, str) else API_SECRET,
        message.encode(),
        hashlib.sha256
    ).hexdigest()

    return hmac.compare_digest(signature, expected)


@app.route('/api/v1/ingest', methods=['POST'])
def ingest_data():
    """Ingest sensor data batch."""
    if not verify_request(request):
        return jsonify({'error': 'unauthorized'}), 401

    data = request.get_json()
    if not data or 'readings' not in data:
        return jsonify({'error': 'invalid payload'}), 400

    readings = data['readings']
    if not isinstance(readings, list) or len(readings) > 2048:
        return jsonify({'error': 'invalid readings: must be list with max 2048 entries'}), 400

    timestamps = []
    values = []

    for r in readings:
        if not isinstance(r, dict) or 'ts' not in r or 'val' not in r:
            return jsonify({'error': 'each reading must have ts and val'}), 400
        try:
            ts = int(r['ts'])
            val = float(r['val'])
            if not (-1e15 < val < 1e15):  # reasonable sensor range
                return jsonify({'error': 'value out of range'}), 400
            timestamps.append(ts)
            values.append(val)
        except (ValueError, TypeError, OverflowError):
            return jsonify({'error': 'invalid reading values'}), 400

    try:
        written = sensor_buffer.write_batch(timestamps, values)
        return jsonify({'status': 'ok', 'written': written})
    except Exception as e:
        return jsonify({'error': 'internal error'}), 500


@app.route('/api/v1/query', methods=['GET'])
def query_data():
    """Query sensor data."""
    if not verify_request(request):
        return jsonify({'error': 'unauthorized'}), 401

    try:
        offset = int(request.args.get('offset', 0))
        length = int(request.args.get('length', 100))

        if length > 1024 or length < 0:
            return jsonify({'error': 'length must be 0-1024'}), 400
        if offset < 0:
            return jsonify({'error': 'offset must be non-negative'}), 400

        results = sensor_buffer.read_range(offset, length)
        return jsonify({'data': results})
    except (ValueError, TypeError):
        return jsonify({'error': 'invalid parameters'}), 400


@app.route('/api/v1/stats', methods=['GET'])
def get_stats():
    """Get buffer statistics."""
    if not verify_request(request):
        return jsonify({'error': 'unauthorized'}), 401
    return jsonify(sensor_buffer.get_stats())


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
